-- Import des courriers arrivées 2005
-- Source : 2005.xlsx (feuille 2005).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N°                -> txt_numdordre (00001/jj-mm-aaaa) et txt_numcourier
--   DATE              -> dt_datearrivee et dt_datecourier
--   PRENOMS + NOM     -> txt_prenomNom et txt_expediteur
--   DESIGNATION       -> txt_objet (libellé d'origine)
--   DESIGNATION       -> txt_designation (liste designationsParCategorie)
--   designation retenue -> txt_categorie
--   TF                -> txt_numTitreFoncier
--   N° LOT            -> txt_numLot
--   AGENTS TRAITEUR   -> txt_agenttraiteur
--   OBSERVATIONS      -> txt_observation
--   CATEGORIE        -> ignorée (toujours Demande SERVICES) ; la catégorie vient de la désignation
--   référence formulaire -> « <N°> du jj-mm-aaaa »
--   NICAD cité dans l'objet -> txt_NICAD
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si l'objet commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Dates d'arrivée illisibles reconstituées sur la ligne voisine : 0
-- Numéros d'arrivée reconstitués entre deux numéros voisins : 1
-- Lignes importées : 2007
-- Lignes non importées :
--   ligne Excel 1179 : N° 1179 sans objet, nom ni titre
--   ligne Excel 2010 : N° d'arrivée absent (Sekhou Ladji TANDJIGORA / Morcellement)
--   ligne Excel 2011 : N° d'arrivée absent (Fatou NDOYE / Morcellement)
--
-- Répartition des catégories :
--    1970  Demande SERVICES
--      28  Information
--       7  Convocation - Invitation
--       2  Réclamation - Signalement
-- Désignations :
--    1351  Morcellements
--     187  Demande de Cession définitive
--     125  Demande de terrain/Echange
--     124  Demande de Régularisation par voie de Bail
--      59  Demande de délimitation
--      57  Duplication de CIC
--      16  Demande d'états des lieux
--      11  Note de service
--      10  Réquisition d'immatriculation
--      10  Autres
--       9  Tribunal
--       8  Autorisation de lotir
--       7  Demande de situation foncière
--       5  Réunion
--       4  Demande d'évaluation
--       3  Réceptions de lotissements
--       3  PV - Compte - rendu
--       3  Décision - Arrêté
--       2  Litiges
--       2  Demande de Titre foncier
--       2  Demande Avis Technique
--       2  Demande d'attestation du Cadastre
--       2  Plainte
--       1  Visite de site
--       1  Demande d'extraits de plan
--       1  Audience Publique
--       1  Circulaire
--       1  Autorisation de construction

SET NAMES utf8mb4;

-- Certains N° TF du classeur dépassent 25 caractères (listes de titres).
ALTER TABLE `arrivees`
  MODIFY `txt_numTitreFoncier` VARCHAR(255) NULL,
  MODIFY `txt_numTitreMere` VARCHAR(255) NULL;

START TRANSACTION;







COMMIT;
